    esc(r.nativeSuccessEvents)+'</td><td>'+esc(r.acceptedByMerchantInbox)+'</td><td>'+
    esc(r.pendingDelivery)+'</td><td>'+esc(r.exhaustedDelivery)+'</td><td>'+
